// Producer
var factory = new ConnectionFactory() { HostName = "localhost" };
using var connection = factory.CreateConnection();
using var channel = connection.CreateModel();
channel.ExchangeDeclare("orders", ExchangeType.Direct);
channel.BasicPublish("orders", "order.created", null,
    Encoding.UTF8.GetBytes("{\"orderId\": 1001}"));

// Consumer
var consumerChannel = connection.CreateModel();
consumerChannel.QueueDeclare("order-processing", durable: true, exclusive: false, autoDelete: false);
consumerChannel.QueueBind("order-processing", "orders", "order.created");
var consumer = new EventingBasicConsumer(consumerChannel);
consumer.Received += (sender, ea) =>
{
    var body = ea.Body.ToArray();
    Console.WriteLine(Encoding.UTF8.GetString(body));
};
consumerChannel.BasicConsume("order-processing", autoAck: true, consumer);
